/* ===== GreenBean Coffee — Shared Styles ===== */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&display=swap');

:root {
  --green: #00824A;
  --green-dark: #006838;
  --green-light: #e6f5ed;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #fdf6e3;
  --cream-bg: #fffbf0;
  --brown: #6f4e37;
  --brown-light: #a67c52;
  --brown-dark: #3e2723;
  --white: #ffffff;
  --gray-50: #fafafa;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.05);
  --shadow: 0 1px 3px rgba(0,0,0,.1), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 6px rgba(0,0,0,.07), 0 2px 4px rgba(0,0,0,.06);
  --shadow-lg: 0 10px 15px rgba(0,0,0,.1), 0 4px 6px rgba(0,0,0,.05);
  --radius: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --transition: .25s ease;
  --font-body: 'DM Sans', sans-serif;
  --font-heading: 'Fraunces', serif;
  --max-width: 1280px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4 { font-family: var(--font-heading); color: var(--forest); line-height: 1.2; }
h1 { font-size: 2.75rem; }
h2 { font-size: 2rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius-full);
  font-weight: 600; font-size: .95rem;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-outline { border: 2px solid var(--green); color: var(--green); background: transparent; }
.btn-outline:hover { background: var(--green); color: var(--white); }
.btn-cream { background: var(--cream); color: var(--forest); }
.btn-cream:hover { background: #edc07a; transform: translateY(-1px); }
.btn-dark { background: var(--forest); color: var(--white); }
.btn-dark:hover { background: #253525; }
.btn-white { background: var(--white); color: var(--green); }
.btn-white:hover { background: var(--gray-100); }

/* ===== Header ===== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--white); border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.site-header.scrolled { box-shadow: var(--shadow); }
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; height: 72px;
}
.logo {
  font-family: var(--font-heading); font-size: 1.5rem; font-weight: 700;
  color: var(--green); display: flex; align-items: center; gap: 8px;
}
.logo-icon { width: 36px; height: 36px; }
.nav-main { display: flex; align-items: center; gap: 32px; }
.nav-main a {
  font-weight: 500; font-size: .95rem; color: var(--gray-700);
  position: relative; padding: 4px 0; transition: color var(--transition);
}
.nav-main a::after {
  content: ''; position: absolute; bottom: -2px; left: 0; width: 0; height: 2px;
  background: var(--green); transition: width var(--transition);
}
.nav-main a:hover { color: var(--green); }
.nav-main a:hover::after { width: 100%; }
.nav-main a.active { color: var(--green); }
.nav-main a.active::after { width: 100%; }
.nav-account { display: flex; align-items: center; gap: 16px; }
.nav-account a { font-size: .9rem; font-weight: 500; color: var(--gray-600); }
.nav-account a:hover { color: var(--green); }
.nav-account .btn { padding: 8px 20px; font-size: .85rem; }
.hamburger { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.hamburger span { display: block; width: 22px; height: 2px; background: var(--gray-700); border-radius: 2px; transition: all var(--transition); }

/* Mobile Nav */
.mobile-nav {
  display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
  background: var(--white); z-index: 99; padding: 24px;
  flex-direction: column; gap: 8px; overflow-y: auto;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  display: block; padding: 14px 0; font-size: 1.1rem; font-weight: 500;
  border-bottom: 1px solid var(--gray-200); color: var(--gray-700);
}
.mobile-nav a:hover { color: var(--green); }

/* ===== Cookie Banner ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--forest); color: var(--white); padding: 24px;
  display: flex; align-items: center; gap: 24px; flex-wrap: wrap;
  box-shadow: 0 -4px 20px rgba(0,0,0,.15);
}
.cookie-banner.hidden { display: none; }
.cookie-banner p { flex: 1; min-width: 260px; font-size: .9rem; line-height: 1.5; }
.cookie-banner .btn { flex-shrink: 0; }

/* ===== Footer ===== */
.site-footer { background: var(--forest); color: var(--cream); padding: 64px 0 32px; }
.footer-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px 48px;
  border-bottom: 1px solid rgba(243,206,161,.2);
}
.footer-col h4 {
  color: var(--white); font-family: var(--font-body); font-size: .95rem;
  font-weight: 700; margin-bottom: 16px; cursor: default;
}
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a { font-size: .85rem; color: var(--cream); opacity: .8; transition: opacity var(--transition); }
.footer-col ul li a:hover { opacity: 1; }
.footer-bottom {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 24px 24px 0;
  font-size: .8rem; opacity: .6;
}
.footer-social { display: flex; gap: 16px; }
.footer-social a { opacity: .7; transition: opacity var(--transition); }
.footer-social a:hover { opacity: 1; }

/* Footer Accordion (mobile) */
.footer-accordion-toggle { display: none; }

/* ===== Hero ===== */
.hero {
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, var(--green-light) 0%, var(--cream-light) 100%);
  min-height: 480px; display: flex; align-items: center;
}
.hero-inner { display: flex; align-items: center; gap: 48px; max-width: var(--max-width); margin: 0 auto; padding: 48px 24px; width: 100%; }
.hero-text { flex: 1; }
.hero-text h1 { margin-bottom: 16px; font-size: 3.25rem; }
.hero-text p { font-size: 1.15rem; color: var(--gray-600); margin-bottom: 28px; max-width: 520px; }
.hero-visual { flex: 1; display: flex; justify-content: center; align-items: center; }
.hero-image {
  width: 420px; height: 420px; border-radius: var(--radius-lg);
  background: linear-gradient(135deg, var(--cream) 0%, #d4a76a 50%, var(--brown-light) 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem; box-shadow: var(--shadow-lg);
  position: relative; overflow: hidden;
}
.hero-image::after {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(circle at 30% 70%, rgba(255,255,255,.2) 0%, transparent 60%);
}

/* ===== Content Sections ===== */
.section { padding: 72px 0; }
.section-alt { background: var(--cream-bg); }
.section-green { background: var(--green); color: var(--white); }
.section-green h2, .section-green h3, .section-green h4 { color: var(--white); }
.section-forest { background: var(--forest); color: var(--cream); }
.section-forest h2, .section-forest h3 { color: var(--cream); }

.content-grid {
  display: flex; align-items: center; gap: 48px;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
}
.content-grid.reverse { flex-direction: row-reverse; }
.content-text { flex: 1; }
.content-text h2 { margin-bottom: 16px; }
.content-text p { font-size: 1.05rem; color: var(--gray-600); margin-bottom: 24px; max-width: 520px; }
.content-visual { flex: 1; display: flex; justify-content: center; }
.content-image {
  width: 100%; max-width: 480px; aspect-ratio: 4/3; border-radius: var(--radius-lg);
  overflow: hidden; box-shadow: var(--shadow-md);
}
.img-placeholder {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 3rem; color: rgba(255,255,255,.5);
}
.img-placeholder.coffee { background: linear-gradient(135deg, #8B6914 0%, #6f4e37 40%, #3e2723 100%); }
.img-placeholder.mango { background: linear-gradient(135deg, #ffd700 0%, #ff8c00 40%, #ff6347 100%); }
.img-placeholder.lavender { background: linear-gradient(135deg, #e6e6fa 0%, #9b8ec4 40%, #6a5acd 100%); }
.img-placeholder.green { background: linear-gradient(135deg, #90ee90 0%, #00824A 40%, #32462F 100%); }
.img-placeholder.cream { background: linear-gradient(135deg, #fff8dc 0%, #F3CEA1 40%, #d4a76a 100%); }
.img-placeholder.berries { background: linear-gradient(135deg, #ff6b6b 0%, #c44569 40%, #6a0572 100%); }

/* ===== Cards ===== */
.card {
  background: var(--white); border-radius: var(--radius-lg);
  overflow: hidden; box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
}
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.card-img { width: 100%; aspect-ratio: 16/10; }
.card-body { padding: 20px; }

/* ===== Tabs ===== */
.tab-list {
  display: flex; gap: 4px; background: var(--gray-100);
  border-radius: var(--radius-full); padding: 4px; overflow-x: auto;
  scrollbar-width: none;
}
.tab-list::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 10px 20px; border-radius: var(--radius-full);
  font-weight: 600; font-size: .85rem; white-space: nowrap;
  color: var(--gray-600); transition: all var(--transition);
}
.tab-btn:hover { color: var(--green); }
.tab-btn.active { background: var(--green); color: var(--white); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ===== Carousel ===== */
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex; gap: 16px; overflow-x: auto;
  scroll-behavior: smooth; scrollbar-width: none;
  padding: 8px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-item { flex: 0 0 220px; }
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  z-index: 2; transition: all var(--transition); font-size: 1.1rem;
  color: var(--gray-700); border: 1px solid var(--gray-200);
}
.carousel-btn:hover { background: var(--green); color: var(--white); border-color: var(--green); }
.carousel-btn.prev { left: -12px; }
.carousel-btn.next { right: -12px; }

/* Gift card */
.gift-card {
  width: 220px; height: 140px; border-radius: var(--radius);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: .85rem; color: var(--white);
  text-align: center; padding: 16px; line-height: 1.3;
  box-shadow: var(--shadow); transition: transform var(--transition);
  position: relative; overflow: hidden;
}
.gift-card::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(135deg, rgba(255,255,255,.15) 0%, transparent 50%);
}
.gift-card:hover { transform: scale(1.05); }
.gift-card span { position: relative; z-index: 1; }

/* ===== Breadcrumb ===== */
.breadcrumb {
  display: flex; align-items: center; gap: 8px;
  padding: 16px 0; font-size: .85rem; color: var(--gray-500);
}
.breadcrumb a { color: var(--gray-500); transition: color var(--transition); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb .sep { opacity: .4; }

/* ===== Menu Layout ===== */
.menu-layout { display: flex; gap: 32px; max-width: var(--max-width); margin: 0 auto; padding: 0 24px 72px; }
.menu-sidebar {
  width: 260px; flex-shrink: 0; position: sticky; top: 96px;
  align-self: flex-start; max-height: calc(100vh - 120px); overflow-y: auto;
}
.menu-sidebar h3 {
  font-family: var(--font-body); font-size: .8rem; text-transform: uppercase;
  letter-spacing: .06em; color: var(--gray-400); margin: 20px 0 8px; padding: 0 12px;
}
.menu-sidebar h3:first-child { margin-top: 0; }
.menu-sidebar a {
  display: block; padding: 8px 12px; border-radius: 8px;
  font-size: .9rem; color: var(--gray-600); transition: all var(--transition);
}
.menu-sidebar a:hover, .menu-sidebar a.active { background: var(--green-light); color: var(--green); font-weight: 600; }
.menu-content { flex: 1; min-width: 0; }
.menu-category { margin-bottom: 56px; }
.menu-category h2 { margin-bottom: 24px; padding-bottom: 12px; border-bottom: 2px solid var(--green-light); }
.menu-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 20px; }
.menu-item {
  background: var(--white); border-radius: var(--radius); overflow: hidden;
  border: 1px solid var(--gray-200); transition: all var(--transition);
}
.menu-item:hover { border-color: var(--green); box-shadow: var(--shadow); }
.menu-item-img { width: 100%; aspect-ratio: 1; }
.menu-item-name { padding: 12px 16px; font-weight: 600; font-size: .9rem; }

/* ===== Rewards ===== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green) 0%, var(--green-dark) 100%);
  color: var(--white); padding: 80px 0; text-align: center;
}
.rewards-hero h1 { color: var(--white); font-size: 3rem; margin-bottom: 12px; }
.rewards-hero p { font-size: 1.15rem; opacity: .9; max-width: 520px; margin: 0 auto 28px; }

.steps-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
}
.step-card {
  text-align: center; padding: 32px 24px;
  background: var(--white); border-radius: var(--radius-lg);
  box-shadow: var(--shadow); transition: transform var(--transition);
}
.step-card:hover { transform: translateY(-4px); }
.step-number {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--green); color: var(--white);
  display: inline-flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1.2rem; margin-bottom: 16px;
}
.step-card h3 { margin-bottom: 8px; }
.step-card p { font-size: .9rem; color: var(--gray-500); }

.tier-cards {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
}
.tier-card {
  background: var(--white); border-radius: var(--radius-lg); padding: 32px;
  border: 2px solid var(--gray-200); transition: all var(--transition);
}
.tier-card:hover { border-color: var(--green); box-shadow: var(--shadow-md); }
.tier-card.gold { border-color: #d4a76a; }
.tier-card.gold:hover { box-shadow: 0 4px 20px rgba(212,167,106,.3); }
.tier-card.reserve { border-color: var(--green); }
.tier-card.reserve:hover { box-shadow: 0 4px 20px rgba(0,130,74,.2); }
.tier-name { font-family: var(--font-heading); font-size: 1.5rem; margin-bottom: 4px; }
.tier-threshold { font-size: .85rem; color: var(--gray-500); margin-bottom: 16px; }
.tier-benefits { font-size: .9rem; color: var(--gray-600); line-height: 1.8; }

.redemption-section { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.redemption-tabs { margin-bottom: 32px; justify-content: center; }
.redemption-card {
  display: flex; align-items: center; gap: 32px;
  background: var(--white); border-radius: var(--radius-lg);
  padding: 40px; box-shadow: var(--shadow);
}
.redemption-icon {
  width: 120px; height: 120px; border-radius: var(--radius-lg);
  display: flex; align-items: center; justify-content: center;
  font-size: 3rem; flex-shrink: 0;
}
.redemption-info h3 { margin-bottom: 8px; }
.redemption-info p { color: var(--gray-600); font-size: .95rem; }
.redemption-value {
  display: inline-block; margin-top: 12px;
  padding: 4px 12px; border-radius: var(--radius-full);
  background: var(--green-light); color: var(--green);
  font-weight: 600; font-size: .85rem;
}

/* ===== Store Locator ===== */
.locator-controls {
  display: flex; gap: 12px; align-items: center; flex-wrap: wrap;
  max-width: var(--max-width); margin: 0 auto; padding: 24px 24px 0;
}
.search-input-wrapper {
  flex: 1; min-width: 280px; position: relative;
}
.search-input {
  width: 100%; padding: 14px 20px 14px 48px;
  border: 2px solid var(--gray-200); border-radius: var(--radius-full);
  font-size: .95rem; font-family: inherit;
  transition: border-color var(--transition);
  background: var(--white);
}
.search-input:focus { outline: none; border-color: var(--green); }
.search-icon {
  position: absolute; left: 18px; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); font-size: 1.1rem; pointer-events: none;
}
.search-suggestions {
  position: absolute; top: 100%; left: 0; right: 0;
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius); margin-top: 4px;
  box-shadow: var(--shadow-lg); z-index: 10; display: none;
}
.search-suggestions.open { display: block; }
.search-suggestions a {
  display: block; padding: 10px 16px; font-size: .9rem;
  color: var(--gray-700); transition: background var(--transition);
}
.search-suggestions a:hover { background: var(--green-light); color: var(--green); }

.order-toggle {
  display: flex; background: var(--gray-100); border-radius: var(--radius-full); padding: 3px;
}
.order-toggle button {
  padding: 10px 20px; border-radius: var(--radius-full);
  font-weight: 600; font-size: .85rem;
  color: var(--gray-600); transition: all var(--transition);
}
.order-toggle button.active { background: var(--green); color: var(--white); }

.filter-btn {
  padding: 10px 20px; border-radius: var(--radius-full);
  border: 2px solid var(--gray-200); font-weight: 600; font-size: .85rem;
  display: flex; align-items: center; gap: 6px;
  color: var(--gray-700); background: var(--white);
  transition: all var(--transition);
}
.filter-btn:hover { border-color: var(--green); color: var(--green); }

.filter-panel {
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  max-height: 0; overflow: hidden; transition: max-height .3s ease;
}
.filter-panel.open { max-height: 200px; padding-top: 16px; }
.filter-options {
  display: flex; gap: 12px; flex-wrap: wrap; padding: 16px;
  background: var(--white); border-radius: var(--radius);
  border: 1px solid var(--gray-200);
}
.filter-chip {
  padding: 8px 16px; border-radius: var(--radius-full);
  border: 1px solid var(--gray-300); font-size: .85rem;
  color: var(--gray-600); transition: all var(--transition);
  background: var(--white);
}
.filter-chip:hover, .filter-chip.active { border-color: var(--green); color: var(--green); background: var(--green-light); }

.locator-layout {
  display: flex; gap: 24px;
  max-width: var(--max-width); margin: 0 auto; padding: 24px;
}
.map-view {
  flex: 1; height: 500px; border-radius: var(--radius-lg);
  background: linear-gradient(135deg, var(--green-light) 0%, var(--cream-light) 50%, var(--gray-100) 100%);
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
  border: 1px solid var(--gray-200);
}
.map-pins {
  position: absolute; inset: 0;
}
.map-pin {
  position: absolute; width: 32px; height: 32px;
  background: var(--green); border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg); box-shadow: var(--shadow);
  display: flex; align-items: center; justify-content: center;
}
.map-pin::after {
  content: ''; width: 10px; height: 10px; background: var(--white);
  border-radius: 50%; transform: rotate(45deg);
}
.results-list { width: 380px; flex-shrink: 0; display: flex; flex-direction: column; gap: 12px; }
.store-card {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius); padding: 16px;
  transition: all var(--transition);
}
.store-card:hover { border-color: var(--green); box-shadow: var(--shadow); }
.store-name { font-weight: 700; margin-bottom: 4px; }
.store-address { font-size: .85rem; color: var(--gray-500); margin-bottom: 8px; }
.store-features { display: flex; gap: 8px; flex-wrap: wrap; }
.store-feature {
  font-size: .75rem; padding: 3px 10px; border-radius: var(--radius-full);
  background: var(--green-light); color: var(--green); font-weight: 500;
}
.store-hours { font-size: .8rem; color: var(--gray-500); margin-top: 8px; }

/* ===== FAQ ===== */
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 0; font-weight: 600; color: var(--gray-700);
  width: 100%; text-align: left; font-size: .95rem;
}
