}
.gift-card:hover { transform: scale(1.05); }
.gift-card span { position: relative; z-index: 1; }

/* ===== Breadcrumb ===== */
.breadcrumb {
  display: flex; align-items: center; gap: 8px;
  padding: 16px 0; font-size: .85rem; color: var(--gray-500);
}
.breadcrumb a { color: var(--gray-500); transition: color var(--transition); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb .sep { opacity: .4; }

/* ===== Menu Layout ===== */
.menu-layout { display: flex; gap: 32px; max-width: var(--max-width); margin: 0 auto; padding: 0 24px 72px; }
.menu-sidebar {
  width: 260px; flex-shrink: 0; position: sticky; top: 96px;
  align-self: flex-start; max-height: calc(100vh - 120px); overflow-y: auto;
}
.menu-sidebar h3 {
  font-family: var(--font-body); font-size: .8rem; text-transform: uppercase;
