/* ===== GreenBean Coffee — Shared Styles ===== */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&display=swap');

:root {
  --green: #00824A;
  --green-dark: #006838;
  --green-light: #e6f5ed;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #fdf6e3;
  --cream-bg: #fffbf0;
  --brown: #6f4e37;
  --brown-light: #a67c52;
  --brown-dark: #3e2723;
  --white: #ffffff;
  --gray-50: #fafafa;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.05);
  --shadow: 0 1px 3px rgba(0,0,0,.1), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 6px rgba(0,0,0,.07), 0 2px 4px rgba(0,0,0,.06);
  --shadow-lg: 0 10px 15px rgba(0,0,0,.1), 0 4px 6px rgba(0,0,0,.05);
  --radius: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --transition: .25s ease;
  --font-body: 'DM Sans', sans-serif;
  --font-heading: 'Fraunces', serif;
  --max-width: 1280px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4 { font-family: var(--font-heading); color: var(--forest); line-height: 1.2; }
h1 { font-size: 2.75rem; }
h2 { font-size: 2rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius-full);
  font-weight: 600; font-size: .95rem;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-outline { border: 2px solid var(--green); color: var(--green); background: transparent; }
.btn-outline:hover { background: var(--green); color: var(--white); }
.btn-cream { background: var(--cream); color: var(--forest); }
.btn-cream:hover { background: #edc07a; transform: translateY(-1px); }
.btn-dark { background: var(--forest); color: var(--white); }
.btn-dark:hover { background: #253525; }
.btn-white { background: var(--white); color: var(--green); }
.btn-white:hover { background: var(--gray-100); }

/* ===== Header ===== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--white); border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.site-header.scrolled { box-shadow: var(--shadow); }
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; height: 72px;
}
.logo {
  font-family: var(--font-heading); font-size: 1.5rem; font-weight: 700;
  color: var(--green); display: flex; align-items: center; gap: 8px;
}
.logo-icon { width: 36px; height: 36px; }
.nav-main { display: flex; align-items: center; gap: 32px; }
.nav-main a {
  font-weight: 500; font-size: .95rem; color: var(--gray-700);
  position: relative; padding: 4px 0; transition: color var(--transition);
}
.nav-main a::after {
  content: ''; position: absolute; bottom: -2px; left: 0; width: 0; height: 2px;
  background: var(--green); transition: width var(--transition);
}
.nav-main a:hover { color: var(--green); }
.nav-main a:hover::after { width: 100%; }
.nav-main a.active { color: var(--green); }
.nav-main a.active::after { width: 100%; }
.nav-account { display: flex; align-items: center; gap: 16px; }
.nav-account a { font-size: .9rem; font-weight: 500; color: var(--gray-600); }
.nav-account a:hover { color: var(--green); }
.nav-account .btn { padding: 8px 20px; font-size: .85rem; }
.hamburger { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.hamburger span { display: block; width: 22px; height: 2px; background: var(--gray-700); border-radius: 2px; transition: all var(--transition); }

/* Mobile Nav */
.mobile-nav {
  display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
  background: var(--white); z-index: 99; padding: 24px;
  flex-direction: column; gap: 8px; overflow-y: auto;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  display: block; padding: 14px 0; font-size: 1.1rem; font-weight: 500;
  border-bottom: 1px solid var(--gray-200); color: var(--gray-700);
}
.mobile-nav a:hover { color: var(--green); }

/* ===== Cookie Banner ===== */
.cookie-banner {
