<script>
// Header scroll shadow
const header = document.getElementById('site-header');
window.addEventListener('scroll', () => header.classList.toggle('scrolled', window.scrollY > 10));

// Mobile nav
const hamburger = document.getElementById('hamburger');
const mobileNav = document.getElementById('mobile-nav');
hamburger.addEventListener('click', () => {
  mobileNav.classList.toggle('open');
  const spans = hamburger.querySelectorAll('span');
  if (mobileNav.classList.contains('open')) {
    spans[0].style.transform = 'rotate(45deg) translate(5px,5px)';
    spans[1].style.opacity = '0';
    spans[2].style.transform = 'rotate(-45deg) translate(5px,-5px)';
  } else {
    spans[0].style.transform = '';
    spans[1].style.opacity = '';
    spans[2].style.transform = '';
  }
});

// Search suggestions
const searchInput = document.getElementById('store-search');
const suggestions = document.getElementById('search-suggestions');

searchInput.addEventListener('focus', () => {
  if (searchInput.value.length > 0) suggestions.classList.add('open');
});
searchInput.addEventListener('input', () => {
  const val = searchInput.value.toLowerCase();
  const items = suggestions.querySelectorAll('a');
  let hasVisible = false;
  items.forEach(item => {
    const match = item.textContent.toLowerCase().includes(val);
    item.style.display = match ? '' : 'none';
    if (match) hasVisible = true;
  });
  suggestions.classList.toggle('open', val.length > 0 && hasVisible);
});
searchInput.addEventListener('blur', () => {
  setTimeout(() => suggestions.classList.remove('open'), 200);
});
suggestions.querySelectorAll('a').forEach(a => {
  a.addEventListener('click', (e) => {
    e.preventDefault();
    searchInput.value = a.dataset.value;
    suggestions.classList.remove('open');
  });
});

// Order type toggle
document.querySelectorAll('#order-toggle button').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('#order-toggle button').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    // Simulate results update
    const list = document.getElementById('results-list');
    list.style.opacity = '0.5';
    setTimeout(() => { list.style.opacity = '1'; }, 300);
  });
});

// Filter panel toggle
document.getElementById('filter-btn').addEventListener('click', () => {
  document.getElementById('filter-panel').classList.toggle('open');
});

// Filter chips
document.querySelectorAll('.filter-chip').forEach(chip => {
  chip.addEventListener('click', () => chip.classList.toggle('active'));
});

// Footer accordion (mobile)
if (window.innerWidth <= 768) {
  document.querySelectorAll('.footer-col h4').forEach(h4 => {
    h4.addEventListener('click', () => h4.parentElement.classList.toggle('open'));
  });
}
</script>
